// Module-map freshness: the generated map must match the tree, byte for
// byte, and the generator's census controls must hold.
//
// docs/module-map.md is generated by scripts/module-map.mjs (Repo
// Legibility Standard §5). A hand edit, or a js change that forgot to
// regenerate, makes this suite fail — staleness becomes a red suite
// instead of a discovery someone makes in six months. The generator runs
// into a temp file, never the working tree: a test that rewrites the
// document it checks would pass by construction and prove nothing.
//
// The two census pins below (95 bridge files, 1,857 publications) are
// stated literals on purpose, in the CONSTRAINTS posture: they are the
// controls that prove the generator still counts the way ADR-013 says
// (distinct names, tokenized, comment-stripped; value and accessor
// counted separately) instead of drifting into counting occurrences.
// When a legitimate change adds, removes, or re-surfaces a js file, the
// discipline is: regenerate the map (`node scripts/module-map.mjs`),
// then update these pins in the same PR, saying why in the PR body.
// Updating a pin alone, without the regenerated map, fails the byte
// comparison below; regenerating without updating a moved pin fails
// here. Never move a pin just to make this suite green.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

const ROOT = process.env.COZYLIBRAM_DIR || path.join(__dirname, '..');

let pass = 0, fail = 0;
const ok = (name, cond) => { cond ? pass++ : fail++; console.log((cond ? 'PASS' : 'FAIL') + ' - ' + name); };

const committedPath = path.join(ROOT, 'docs', 'module-map.md');
ok('committed module map exists', fs.existsSync(committedPath));

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'module-map-'));
const generatedPath = path.join(tmpDir, 'module-map.md');
let generated = null;
try {
  execFileSync(process.execPath,
    [path.join(ROOT, 'scripts', 'module-map.mjs'), '--root', ROOT, '--out', generatedPath],
    { stdio: 'pipe' });
  generated = fs.readFileSync(generatedPath);
} catch (e) {
  console.log('generator failed: ' + (e.stderr ? e.stderr.toString() : e.message));
}
ok('generator runs against the current tree', generated !== null);

if (generated !== null) {
  const committed = fs.readFileSync(committedPath);
  ok('committed map is byte-identical to a fresh generation', generated.equals(committed));
  if (!generated.equals(committed)) {
    const g = generated.toString('utf8').split('\n');
    const c = committed.toString('utf8').split('\n');
    for (let i = 0; i < Math.max(g.length, c.length); i++) {
      if (g[i] !== c[i]) {
        console.log('  first difference at line ' + (i + 1) + ':');
        console.log('    generated: ' + (g[i] ?? '<missing>'));
        console.log('    committed: ' + (c[i] ?? '<missing>'));
        break;
      }
    }
    console.log('  regenerate with: node scripts/module-map.mjs');
  }

  const text = generated.toString('utf8');
  ok('map carries the generated marker on its first line',
    text.startsWith('<!-- GENERATED by scripts/module-map.mjs — do not edit; regenerate. -->'));

  const summaryCount = (label) => {
    const m = new RegExp('\\| ' + label.replace(/[()|]/g, '\\$&') + ' \\| (\\d+) \\|').exec(text);
    return m ? Number(m[1]) : null;
  };

  // Census controls — stated literals; see the header comment for the
  // regenerate-then-update discipline that governs moving them.
  ok('95 files publish on window through bridges (ADR-013 controls)',
    summaryCount('Files with bridge publications') === 95);
  ok('1,857 distinct bridge publications (ADR-013 controls)',
    summaryCount('Bridge publications (distinct)') === 1857);
  ok('publication split is 1,837 value + 20 accessor',
    summaryCount('— value-published') === 1837 && summaryCount('— accessor-published') === 20);

  // Structure: one table row per js file in the tree, so a file can
  // never be silently absent from the map.
  const jsCount = fs.readdirSync(path.join(ROOT, 'js')).filter(f => f.endsWith('.js')).length;
  const rowCount = (text.match(/^\| `js\//gm) || []).length;
  ok('map has one row per js file', rowCount === jsCount);

  // The wired graph, as it stands: js/060-metadata.js imports seedTropes
  // from js/061-gbooks-key.js, and js/061 imports nothing.
  const rowFor = (file) => text.split('\n').find(l => l.startsWith('| `js/' + file + '` |')) || '';
  ok('js/060-metadata.js imports seedTropes from js/061-gbooks-key.js',
    rowFor('060-metadata.js').includes('`061-gbooks-key.js`: seedTropes'));
  ok('js/061-gbooks-key.js imports nothing',
    rowFor('061-gbooks-key.js').split('|')[4].trim() === '—');
}

fs.rmSync(tmpDir, { recursive: true, force: true });

console.log('\n' + pass + ' passed, ' + fail + ' failed');
process.exit(fail ? 1 : 0);
